-- Separate anonymous and authenticated policy roles; function privileges are checked even in unreachable CASE branches.
alter policy live_chat_messages_public_read on public.live_chat_messages to authenticated using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public')) or public.rb_live_can_access(stream_id,(select auth.uid())) or (select public.rb_is_admin(1))) and not coalesce(is_deleted,false));
create policy live_chat_messages_anon_public_read on public.live_chat_messages for select to anon using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public'))) and not coalesce(is_deleted,false));
alter policy live_reactions_public_read on public.live_reactions to authenticated using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public')) or public.rb_live_can_access(stream_id,(select auth.uid())) or (select public.rb_is_admin(1))));
create policy live_reactions_anon_public_read on public.live_reactions for select to anon using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public'))));
alter policy live_member_activity_public_read on public.live_member_activity to authenticated using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public')) or public.rb_live_can_access(stream_id,(select auth.uid())) or (select public.rb_is_admin(1))));
create policy live_member_activity_anon_public_read on public.live_member_activity for select to anon using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public'))));
alter policy live_stream_members_public_read on public.live_stream_members to authenticated using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public')) or public.rb_live_can_access(stream_id,(select auth.uid())) or (select public.rb_is_admin(1))));
create policy live_stream_members_anon_public_read on public.live_stream_members for select to anon using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public'))));
alter policy live_recordings_select_public on public.live_recordings to authenticated using ((visibility='public' and status in ('ready','completed','published','processed')) or (select auth.uid()) in (creator_id,user_id) or (select public.rb_is_admin(1)));
create policy live_recordings_anon_public_read on public.live_recordings for select to anon using (visibility='public' and status in ('ready','completed','published','processed'));
alter policy feed_posts_public_read on public.feed_posts to authenticated using ((visibility='public' and coalesce(moderation_state,'clear') in ('clear','approved')) or user_id=(select auth.uid()) or (select public.rb_is_admin(1)));
create policy feed_posts_anon_public_read on public.feed_posts for select to anon using (visibility='public' and coalesce(moderation_state,'clear') in ('clear','approved'));
